<?php defined( 'ABSPATH' ) || exit;
$metrics = is_array( $metrics ) ? $metrics : array();
$reviews = is_array( $reviews ) ? $reviews : array( 'items' => array(), 'page' => 1, 'pages' => 1 );
?>
<div class="pcr pcr-dashboard" id="petish-review-studio">
    <header class="pcr-heading"><div><p class="pcr-eyebrow"><?php esc_html_e( 'Your review studio', 'petish-passport' ); ?></p><h2><?php esc_html_e( 'Your little reviews. A little more love.', 'petish-passport' ); ?></h2><p><?php esc_html_e( 'Share what works for your small pet. Help someone find their perfect fit.', 'petish-passport' ); ?></p></div></header>
    <dl class="pcr-stats" aria-label="<?php esc_attr_e( 'Your review and reaction totals', 'petish-passport' ); ?>">
        <?php foreach ( array( 'published' => array( __( 'Published reviews', 'petish-passport' ), __( 'Approved contributions', 'petish-passport' ) ), 'pending' => array( __( 'Pending review', 'petish-passport' ), __( 'Awaiting moderation', 'petish-passport' ) ), 'helpful' => array( __( 'Helpful', 'petish-passport' ), __( 'Likes received', 'petish-passport' ) ), 'not_helpful' => array( __( 'Not helpful', 'petish-passport' ), __( 'Dislikes received', 'petish-passport' ) ) ) as $key => $labels ) : ?><div class="pcr-stat"><dt><?php echo esc_html( $labels[0] ); ?></dt><dd><?php echo esc_html( number_format_i18n( max( 0, (int) ( $metrics[ $key ] ?? 0 ) ) ) ); ?></dd><p><?php echo esc_html( $labels[1] ); ?></p></div><?php endforeach; ?>
    </dl>
    <p class="pcr-small pcr-stats-note"><?php esc_html_e( 'Likes and dislikes are reactions received on your published reviews. They do not affect member status.', 'petish-passport' ); ?></p>
    <div class="pcr-studio-grid"><section class="pcr-panel" id="pcr-composer" aria-labelledby="pcr-composer-title">
        <h3 id="pcr-composer-title"><?php echo esc_html( $product ? __( 'What’s their new favourite?', 'petish-passport' ) : __( 'Choose a product to review.', 'petish-passport' ) ); ?></h3>
        <?php if ( $product ) : ?>
            <div class="pcr-selected-product"><?php echo wp_kses_post( $product->get_image( 'woocommerce_thumbnail', array( 'loading' => 'lazy' ) ) ); ?><div><strong><?php echo esc_html( $product->get_name() ); ?></strong><a class="pcr-small" href="<?php echo esc_url( get_permalink( $product->get_id() ) ); ?>"><?php esc_html_e( 'View product', 'petish-passport' ); ?> →</a></div><a class="pcr-small" href="<?php echo esc_url( Petish_Customer_Reviews_UI::url() ); ?>#pcr-composer"><?php esc_html_e( 'Change', 'petish-passport' ); ?></a></div>
            <?php Petish_Customer_Reviews_UI::template( 'form', compact( 'product', 'values' ) ); ?>
        <?php else : ?>
            <p><?php esc_html_e( 'Search for a product you have used, or choose “Write a review” on its product page.', 'petish-passport' ); ?></p>
            <form class="pcr-product-search" method="get" action="<?php echo esc_url( wc_get_page_permalink( 'myaccount' ) ); ?>#pcr-composer"><input type="hidden" name="my-reviews" value="1"><label for="pcr-product-search"><?php esc_html_e( 'Product name', 'petish-passport' ); ?></label><div><input id="pcr-product-search" type="search" name="pcr_search" value="<?php echo esc_attr( $search ); ?>" minlength="2" maxlength="80" required><button class="pcr-button" type="submit"><?php esc_html_e( 'Search', 'petish-passport' ); ?></button></div></form>
            <?php if ( strlen( $search ) >= 2 ) : ?><ul class="pcr-product-results"><?php $matches = 0; foreach ( $products as $candidate ) : if ( post_password_required( $candidate->get_id() ) || ! $candidate->get_reviews_allowed() ) { continue; } $matches++; ?><li><a href="<?php echo esc_url( Petish_Customer_Reviews_UI::url( array( 'pcr_product' => $candidate->get_id() ) ) ); ?>#pcr-composer"><?php echo esc_html( $candidate->get_name() ); ?><span aria-hidden="true"> →</span></a></li><?php endforeach; ?></ul><?php if ( ! $matches ) : ?><p class="pcr-small"><?php esc_html_e( 'No reviewable products matched. Try another product name.', 'petish-passport' ); ?></p><?php endif; endif; ?>
            <p class="pcr-small"><?php esc_html_e( 'All signed-in customers can share first-hand experiences. Verified purchases receive a separate label.', 'petish-passport' ); ?></p>
        <?php endif; ?>
    </section><aside class="pcr-sidebar"><?php Petish_Customer_Reviews_UI::template( 'progress', compact( 'metrics' ) ); ?><div class="pcr-panel"><h3><?php esc_html_e( 'Small details. Big help.', 'petish-passport' ); ?></h3><p><?php esc_html_e( 'Tell us who it is for, what they loved, and anything you wish you had known. Honest low ratings are just as welcome as high ones.', 'petish-passport' ); ?></p><p class="pcr-small"><?php esc_html_e( 'One qualifying review per product. Colour and size variants count together. Only approved reviews advance your status.', 'petish-passport' ); ?></p></div></aside></div>
    <section class="pcr-my-reviews" id="pcr-my-reviews" aria-labelledby="pcr-my-reviews-title"><h3 id="pcr-my-reviews-title"><?php esc_html_e( 'Your reviews', 'petish-passport' ); ?></h3><nav class="pcr-status-tabs" aria-label="<?php esc_attr_e( 'Review status', 'petish-passport' ); ?>"><?php foreach ( array( 'published' => __( 'Published', 'petish-passport' ), 'pending' => __( 'Pending review', 'petish-passport' ), 'withdrawn' => __( 'Withdrawn', 'petish-passport' ) ) as $key => $label ) : ?><a href="<?php echo esc_url( Petish_Customer_Reviews_UI::url( array( 'pcr_status' => $key ) ) ); ?>#pcr-my-reviews" <?php echo $status === $key ? 'aria-current="page"' : ''; ?>><?php echo esc_html( $label ); ?><?php if ( isset( $metrics[ $key ] ) ) : ?><span><?php echo esc_html( number_format_i18n( (int) $metrics[ $key ] ) ); ?></span><?php endif; ?></a><?php endforeach; ?></nav>
        <?php if ( empty( $reviews['items'] ) ) : ?><div class="pcr-empty"><p><?php echo esc_html( 'pending' === $status ? __( 'You have no reviews awaiting moderation.', 'petish-passport' ) : ( 'withdrawn' === $status ? __( 'You have no withdrawn reviews.', 'petish-passport' ) : __( 'Your published reviews will appear here after moderation.', 'petish-passport' ) ) ); ?></p></div><?php else : foreach ( $reviews['items'] as $review ) { Petish_Customer_Reviews_UI::template( 'card', array( 'review' => $review, 'owner' => true ) ); } endif; ?>
        <?php Petish_Customer_Reviews_UI::pagination( $reviews, Petish_Customer_Reviews_UI::url( array( 'pcr_status' => $status ) ), 'pcr_page', 'pcr-my-reviews' ); ?>
    </section>
</div>
